"""The shared fixture's `scheduling` cases, written by `just fixtures`."""

import json
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

from climb.knowledge.schedule import history, passed, replay, servable, state
from climb.schema.knowledge import Answer, OpenGrade

FIXTURE = Path(__file__).parent / "fixtures" / "knowledge" / "scheduling.json"
ABOUT = (
    "The scheduling cases are generated by `just fixtures` from climb.knowledge.schedule. "
    "The other sections were generated outside this repository, and are regenerated once a "
    "server feature reads their rules. Do not edit by hand."
)
# the TypeScript core's name for the glossary's retained
STATE_NAMES = {"retained": "mastered"}

T0 = datetime.fromisoformat("2026-01-05T09:00:00+00:00")
GOOD: dict[str, Any] = {"ok": True}
HARD: dict[str, Any] = {"ok": True, "guess": True}
AGAIN: dict[str, Any] = {"ok": False}

type Line = dict[str, Any]


def iso(at: datetime) -> str:
    return at.isoformat(timespec="seconds")


def at(days: float = 0, seconds: int = 0) -> str:
    return iso(T0 + timedelta(days=days, seconds=seconds))


def line(t: str, kind: dict[str, Any]) -> Line:
    return {"t": t, "course": "py", "id": "q1", **kind}


def r(days: float, kind: dict[str, Any], seconds: int = 0) -> Line:
    return line(at(days, seconds), kind)


def graded(days: float, grade: str) -> Line:
    return line(at(days), {"ok": grade == "k", "grade": grade})


def answer(n: int, record: Line) -> Answer:
    t = datetime.fromisoformat(record["t"])
    return Answer(
        id=f"a-{n}",
        client_id=f"c-{n}",
        user_id="u-4f9c2a",
        device="d-1",
        at=t,
        created_at=t,
        question_id=f"{record['course']}:{record['id']}",
        correct=record["ok"],
        guess=record.get("guess", False),
        grade=OpenGrade(record["grade"]) if "grade" in record else None,
    )


def expected(records: list[Line], nows: list[str]) -> dict[str, Any]:
    reviews = next(iter(history(answer(n, x) for n, x in enumerate(records)).values()), [])
    moments = [datetime.fromisoformat(n) for n in nows]
    memory = replay(reviews)
    return {
        "ratings": [int(x.rating) for x in reviews],
        "stability": memory.stability if memory else None,
        "difficulty": memory.difficulty if memory else None,
        "due": iso(memory.due) if memory else None,
        "passed": passed(reviews),
        "status": [STATE_NAMES.get(s, s) for s in (state(reviews, m) for m in moments)],
        "ready": [servable(reviews, m) for m in moments],
    }


def due_of(records: list[Line], days: float = 0, minutes: float = 0) -> str:
    due = datetime.fromisoformat(expected(records, [])["due"])
    return iso(due + timedelta(days=days, minutes=minutes))


def chain(n: int) -> list[Line]:
    """Good reviews, each at the moment the replay says the question is due."""
    records = [r(0, GOOD)]
    for _ in range(n):
        records.append(line(due_of(records), GOOD))
    return records


LONG = chain(8)
LAPSE = [*LONG, line(due_of(LONG), AGAIN)]
RELEARNED = [*LAPSE, line(due_of(LONG, minutes=10), GOOD)]
RETAINED = chain(4)
GRADUATED = [r(0, GOOD), r(0, GOOD, 600)]
CASES: list[tuple[str, list[Line], list[str]]] = [
    ("new card Good: 10-minute step", [r(0, GOOD)], [at(0, 300), at(0, 600)]),
    ("Good again after 10 minutes graduates", GRADUATED, [at(0.5), at(5)]),
    ("new card Again: back to the 1-minute step", [r(0, AGAIN)], [at(0, 30), at(0, 60)]),
    ("old miss stays weak and is ready", [r(0, AGAIN)], [at(90)]),
    ("old correct guess stays weak and is ready", [*GRADUATED, r(3, HARD)], [at(90)]),
    (
        "Again, 1 minute, Good, 10 minutes, Good",
        [r(0, AGAIN), r(0, GOOD, 60), r(0, GOOD, 660)],
        [at(1)],
    ),
    ("new card Hard: 5.5-minute step", [r(0, HARD)], [at(0, 300), at(0, 330)]),
    (
        "Again during the 10-minute step: back to step 0",
        [r(0, GOOD), r(0, AGAIN, 600)],
        [at(0, 630), at(0, 660)],
    ),
    ("card knew: Good", [graded(0, "k")], [at(0.5)]),
    ("card partly: Hard", [graded(0, "p")], [at(0, 600)]),
    ("card didn't: Again", [graded(0, "n")], [at(0, 900)]),
    ("early review the same day", [*GRADUATED, r(0.25, GOOD)], [at(1)]),
    ("early review before due", [*GRADUATED, r(2, GOOD), r(4, GOOD)], [at(5)]),
    ("late review", [*GRADUATED, r(30, GOOD)], [at(31), at(400)]),
    ("Hard in review stays weak", [*GRADUATED, r(3, HARD)], [at(4), at(60)]),
    ("long Good chain passes 60 days", LONG, [due_of(LONG, -1), due_of(LONG)]),
    (
        "lapse: Review to Relearning, stability reduced",
        LAPSE,
        [due_of(LONG, minutes=5), due_of(LONG, minutes=10)],
    ),
    ("relearned: Relearning to Review", RELEARNED, [due_of(LONG, minutes=60)]),
    ("mastered at 21 days stability", RETAINED, [due_of(RETAINED, -1), due_of(RETAINED)]),
    ("records out of order", [r(9, GOOD), r(0, GOOD), r(3, GOOD)], [at(10)]),
    ("no attempts", [], [at(0)]),
]


def scheduling() -> list[dict[str, Any]]:
    return [
        {"name": name, "records": records, "now": nows, "expected": expected(records, nows)}
        for name, records, nows in CASES
    ]


def main() -> None:
    fixture = json.loads(FIXTURE.read_text())
    fixture["about"] = ABOUT
    fixture["scheduling"] = scheduling()
    FIXTURE.write_text(json.dumps(fixture, indent=1, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()
